import sys,json,_codecs,codecs
rows=json.load(sys.stdin)
for row in rows:
 events=[]
 def recover(e):
  events.append([e.encoding,list(e.object),e.start,e.end,e.reason])
  if len(events)==1:
   e.object=bytes(row['replacement'])
   return ('!',0)
  return ('?',len(e.object))
 codecs.register_error('probe',recover)
 try:
  s,n=_codecs.utf_7_decode(bytes(row['input']),'probe',row['final'])
  result={'text':list(map(ord,s)),'consumed':n,'events':events}
 except Exception as e: result={'error':[type(e).__name__,str(e)],'events':events}
 print(json.dumps(result))
